"""Bounded exact decimal parsing; incoming market values are never rounded."""

from dataclasses import dataclass
from decimal import Context, Decimal, InvalidOperation, ROUND_HALF_EVEN, localcontext
import json
import re

DECIMAL_CONTEXT_VERSION = "decimal-v1-p80-half-even"
DECIMAL_CONTEXT = Context(prec=80, rounding=ROUND_HALF_EVEN)
MAX_MARKET_DATA_BYTES = 32 * 1024 * 1024
_DECIMAL_TEXT = re.compile(
    r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?\Z"
)


@dataclass(frozen=True)
class DecimalPolicy:
    max_chars: int = 128
    max_digits: int = 38
    max_exponent: int = 38
    max_abs: Decimal = Decimal("1e30")

    def __post_init__(self):
        for value in (self.max_chars, self.max_digits, self.max_exponent):
            if type(value) is not int or value <= 0:
                raise ValueError("decimal policy bounds must be positive integers")
        if (
            not isinstance(self.max_abs, Decimal)
            or not self.max_abs.is_finite()
            or self.max_abs <= 0
        ):
            raise ValueError("invalid decimal magnitude bound")


DEFAULT_DECIMAL_POLICY = DecimalPolicy()
# Explicit derived-output bound; native source/model constructors keep their policy.
DERIVED_DECIMAL_POLICY = DecimalPolicy(
    max_chars=512, max_digits=80, max_exponent=256, max_abs=Decimal("1e120")
)


def decimal(
    value: str | int | Decimal,
    *,
    positive: bool = False,
    nonnegative: bool = False,
    policy: DecimalPolicy = DEFAULT_DECIMAL_POLICY,
) -> Decimal:
    if isinstance(value, bool) or not isinstance(value, (str, int, Decimal)):
        raise ValueError(
            "decimal requires original text, integer, or Decimal; floats forbidden"
        )
    if isinstance(value, str):
        if len(value) > policy.max_chars or not _DECIMAL_TEXT.fullmatch(value):
            raise ValueError("invalid decimal text")
    elif isinstance(value, int) and value.bit_length() > policy.max_digits * 4:
        raise ValueError("decimal integer too large")
    try:
        result = Decimal(value)
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("invalid decimal") from exc
    if not result.is_finite():
        raise ValueError("nonfinite decimal")
    parts = result.as_tuple()
    if (
        len(parts.digits) > policy.max_digits
        or abs(int(parts.exponent)) > policy.max_exponent
    ):
        raise ValueError("decimal precision/exponent exceeded")
    if result.copy_abs() > policy.max_abs:
        raise ValueError("decimal magnitude exceeded")
    if positive and result <= 0 or nonnegative and result < 0:
        raise ValueError("invalid decimal sign")
    return result


def canonical_decimal(
    value: Decimal, *, policy: DecimalPolicy = DEFAULT_DECIMAL_POLICY
) -> str:
    value = decimal(value, policy=policy)
    if not value:
        return "0"
    text = format(value, "f")
    return text.rstrip("0").rstrip(".") if "." in text else text


def validate_increment(
    value: Decimal, increment: Decimal, *, name: str = "value"
) -> None:
    value, increment = decimal(value), decimal(increment, positive=True)
    with localcontext(DECIMAL_CONTEXT):
        if value % increment:
            raise ValueError(f"{name} is off increment")


def scaled_decimal(value: int, scale: int) -> Decimal:
    if type(value) is not int or type(scale) is not int or not 0 <= scale <= 38:
        raise ValueError("invalid scaled integer")
    if value.bit_length() > 128:
        raise ValueError("scaled integer overflow")
    with localcontext(DECIMAL_CONTEXT):
        return decimal(Decimal(value).scaleb(-scale))


def nonnegative_int(value: int, name: str = "integer") -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(f"{name} must be a nonnegative integer")
    return value


def text(value: str, name: str = "identifier") -> str:
    if (
        not isinstance(value, str)
        or not value
        or len(value) > 512
        or any(ord(c) < 32 for c in value)
    ):
        raise ValueError(f"invalid {name}")
    return value


def choice(value: str, allowed: tuple[str, ...], name: str) -> None:
    if value not in allowed:
        raise ValueError(f"invalid {name}: {value!r}")


def exact_json_loads(payload: bytes | str, *, max_bytes: int = MAX_MARKET_DATA_BYTES):
    if not isinstance(payload, (bytes, str)) or len(payload) > max_bytes:
        raise ValueError("JSON message size exceeded")

    def reject_constant(value):
        raise ValueError(f"nonfinite JSON number: {value}")

    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError(f"duplicate JSON key: {key}")
            result[key] = value
        return result

    try:
        return json.loads(
            payload,
            parse_float=decimal,
            parse_int=lambda s: int(decimal(s)),
            parse_constant=reject_constant,
            object_pairs_hook=pairs,
        )
    except (UnicodeError, RecursionError, json.JSONDecodeError) as exc:
        raise ValueError("malformed JSON") from exc

src/workstation/projection.py.source:
"""Single-owner deterministic downstream projection shared by capture and replay.

The recorder owns this projection on its writer thread: it never snapshots a live
supervisor's concurrently mutating reducer. Raw replay uses the live pure decode
and normalized evidence helpers; normalized replay omits only source decoding.
"""

from collections import OrderedDict
from dataclasses import replace
from hashlib import sha256
from typing import TYPE_CHECKING, Iterable

from .adapter_catalog import create_adapter
from .adapters.base import Adapter
from .book import Book, BookCheckpoint, BookReducer, ReducerState
from .events import Control, EventEnvelope, Gap, RawFrame, SegmentId, StreamId
from .ingestion import decode_frame, make_snapshot_reducer, normalize_events
from .quality import SourceMode
from .wire import dumps, loads

if TYPE_CHECKING:
    from .recording import RecordedBatch, StreamSpec

_Auxiliary = tuple[
    int,
    int,
    str,
    tuple[tuple[str, str, int, str, bool, str], ...],
    tuple[tuple[str, str, str, str], ...],
]


def adapter_for_stream(spec: "StreamSpec") -> Adapter:
    """Select only built-in adapters; manifests cannot name executable classes."""
    config = dict(spec.adapter_config)
    if spec.key.venue == "hyperliquid":
        if set(config) - {"dex"}:
            raise ValueError("unsupported Hyperliquid adapter configuration")
        from .adapters.hyperliquid import HyperliquidAdapter

        adapter: Adapter = HyperliquidAdapter(dex=config.get("dex", ""))
    else:
        if config:
            raise ValueError("unsupported adapter configuration")
        adapter = create_adapter(spec.key.venue)
    prototype = adapter.new_reducer(spec.instrument, spec.key)
    if (prototype.adapter_revision, prototype.config_hash) != (
        spec.adapter_revision,
        spec.config_hash,
    ):
        raise ValueError("incompatible recorded adapter revision/configuration")
    return adapter


class RecordingProjection:
    """Bounded stream state; caller serializes access at delivery boundaries."""

    def __init__(
        self,
        streams: Iterable["StreamSpec"] = (),
        *,
        dedup_capacity: int = 50_000,
        poll_interval: float = 2.0,
    ):
        if type(dedup_capacity) is not int or dedup_capacity < 1:
            raise ValueError("invalid dedup capacity")
        if not 0 < poll_interval < float("inf"):
            raise ValueError("invalid polling interval")
        self.dedup_capacity = dedup_capacity
        self.poll_interval = poll_interval
        self.specs: dict[StreamId, StreamSpec] = {}
        self.adapters: dict[StreamId, Adapter] = {}
        self.reducers: dict[StreamId, BookReducer] = {}
        self.modes: dict[StreamId, SourceMode] = {}
        self.dedup: OrderedDict[tuple[str, str, str, str], None] = OrderedDict()
        self._checkpoint_cache: dict[StreamId, BookCheckpoint] = {}
        for spec in streams:
            self.register_stream(spec)

    def register_stream(self, spec: "StreamSpec") -> None:
        if spec.stream_id in self.specs:
            if self.specs[spec.stream_id] != spec:
                raise ValueError("stream metadata replacement is forbidden")
            return
        self.adapters[spec.stream_id] = adapter_for_stream(spec)
        self.specs[spec.stream_id] = spec

    def _start(
        self,
        stream_id: StreamId,
        epoch: int,
        segment_id: SegmentId,
        mode: SourceMode,
        *,
        capture_complete: bool = True,
    ) -> BookReducer:
        spec, adapter = self.specs[stream_id], self.adapters[stream_id]
        if mode == "rest_snapshot":
            reducer = make_snapshot_reducer(
                adapter,
                spec.instrument,
                spec.key,
                epoch=epoch,
                segment_id=segment_id,
                poll_interval=self.poll_interval,
            )
        else:
            reducer = adapter.new_reducer(spec.instrument, spec.key)
            reducer.reset(epoch, segment_id)
        reducer.quality = replace(reducer.quality, capture_complete=capture_complete)
        self.reducers[stream_id], self.modes[stream_id] = reducer, mode
        return reducer

    def _ensure(self, event: EventEnvelope) -> BookReducer:
        spec = self.specs.get(event.stream_id)
        if (
            spec is None
            or spec.key != event.key
            or (spec.instrument.metadata_version != event.instrument_metadata_version)
        ):
            raise ValueError("unregistered or incompatible event stream")
        reducer = self.reducers.get(event.stream_id)
        if isinstance(event.payload, Control) and event.payload.kind == "source_change":
            if reducer is not None and event.connection_epoch <= reducer.epoch:
                raise ValueError("nonadvancing recorded source epoch")
            return self._start(
                event.stream_id,
                event.connection_epoch,
                event.segment_id,
                event.source_mode,
                capture_complete=(
                    (reducer.quality.capture_complete if reducer else True)
                    and event.payload.detail != "capture_incomplete"
                ),
            )
        if reducer is None:
            reducer = self._start(
                event.stream_id,
                event.connection_epoch,
                event.segment_id,
                event.source_mode,
            )
        return reducer

    def apply_batch(self, batch: "RecordedBatch") -> tuple[EventEnvelope, ...]:
        return self.apply_events(batch.events)

    def apply_events(
        self,
        events: tuple[EventEnvelope, ...],
        *,
        decoded: bool = False,
        recorded_events: tuple[EventEnvelope, ...] | None = None,
    ) -> tuple[EventEnvelope, ...]:
        if not events:
            return ()
        first = events[0]
        self._checkpoint_cache.pop(first.stream_id, None)
        reducer = self._ensure(first)
        # Live source controls announce the already-reset reducer, not a second
        # invalidation of its pristine state. Preserve their observer delivery.
        if isinstance(first.payload, Control) and first.payload.kind == "source_change":
            if len(events) != 1:
                raise ValueError("source change must be a separate transaction")
            return events
        reduction = (
            reducer.invalidate(first)
            if len(events) == 1 and isinstance(first.payload, Gap)
            else reducer.apply(events)
        )
        return normalize_events(
            events,
            reduction.events,
            self.dedup,
            self.dedup_capacity,
            recorded_events=recorded_events if decoded else events,
        )

    def process_raw(
        self,
        frame: RawFrame,
        *,
        segment_id: SegmentId,
        source_mode: SourceMode,
        recorded_events: tuple[EventEnvelope, ...] | None = None,
    ) -> tuple[EventEnvelope, ...]:
        spec = self.specs[frame.stream_id]
        events = decode_frame(
            self.adapters[frame.stream_id],
            spec.instrument,
            spec.key,
            frame,
            SegmentId(segment_id),
            source_mode,
        )
        if recorded_events is not None:
            if len(events) != len(recorded_events):
                raise ValueError("recorded transaction length differs from source")
            # Local processing observations are not present in exchange bytes.
            # Restore them before reduction so staged-event checkpoints match
            # normalized replay; the caller still compares all native evidence.
            events = tuple(
                replace(
                    event,
                    process_start_mono_ns=recorded.process_start_mono_ns,
                    process_end_mono_ns=recorded.process_end_mono_ns,
                    publish_mono_ns=recorded.publish_mono_ns,
                )
                for event, recorded in zip(events, recorded_events, strict=True)
            )
        return self.apply_events(events, decoded=True, recorded_events=recorded_events)

    def books(self) -> tuple[Book, ...]:
        return tuple(
            reducer.book
            for _, reducer in sorted(self.reducers.items())
            if reducer.book is not None
        )

    def _checkpoints(self) -> dict[StreamId, BookCheckpoint]:
        for stream, reducer in self.reducers.items():
            if stream not in self._checkpoint_cache:
                self._checkpoint_cache[stream] = reducer.checkpoint()
        return self._checkpoint_cache

    def checkpoints(self) -> tuple[BookCheckpoint, ...]:
        return tuple(
            checkpoint
            for _, checkpoint in sorted(self._checkpoints().items())
            if checkpoint.stream_id is not None
        )

    def checkpoint_state(self) -> bytes:
        streams = []
        checkpoints = self._checkpoints()
        for stream_id, reducer in sorted(self.reducers.items()):
            checkpoint = checkpoints[stream_id]
            streams.append(
                (
                    str(stream_id),
                    self.modes[stream_id],
                    reducer.epoch,
                    str(reducer.segment_id),
                    reducer.quality.capture_complete,
                    checkpoint.state_hash if checkpoint.stream_id is not None else "",
                )
            )
        return dumps(
            (
                1,
                self.dedup_capacity,
                str(self.poll_interval),
                tuple(streams),
                tuple(self.dedup),
            ),
            canonical=False,
        )

    def restore(
        self,
        checkpoints: Iterable[BookCheckpoint],
        auxiliary: bytes,
    ) -> None:
        version, capacity, interval, streams, dedup = loads(auxiliary, _Auxiliary)
        if (
            version != 1
            or capacity != self.dedup_capacity
            or interval != str(self.poll_interval)
        ):
            raise ValueError("incompatible projection checkpoint")
        if len(dedup) > capacity or len(set(dedup)) != len(dedup):
            raise ValueError("invalid checkpoint dedup history")
        saved = {checkpoint.stream_id: checkpoint for checkpoint in checkpoints}
        required = {StreamId(row[0]) for row in streams if row[5]}
        if set(saved) != required or len({row[0] for row in streams}) != len(streams):
            raise ValueError("incomplete projection checkpoint group")
        candidate = RecordingProjection(
            self.specs.values(),
            dedup_capacity=self.dedup_capacity,
            poll_interval=self.poll_interval,
        )
        for stream, mode, epoch, segment, complete, state_hash in streams:
            stream_id = StreamId(stream)
            if mode not in (
                "ws_delta",
                "ws_snapshot",
                "rest_snapshot",
                "demo",
                "replay",
            ):
                raise ValueError("invalid checkpoint source mode")
            reducer = candidate._start(
                stream_id,
                epoch,
                SegmentId(segment),
                mode,
                capture_complete=complete,
            )
            if state_hash:
                checkpoint = saved[stream_id]
                if checkpoint.state_hash != state_hash:
                    raise ValueError("checkpoint group state mismatch")
                reducer.restore(checkpoint)
        candidate.dedup.update((identity, None) for identity in dedup)
        self.reducers, self.modes, self.dedup = (
            candidate.reducers,
            candidate.modes,
            candidate.dedup,
        )
        self._checkpoint_cache.clear()

    @property
    def book_hash(self) -> str:
        return sha256(dumps(self.books())).hexdigest()

    @property
    def state_hash(self) -> str:
        # Last source-envelope payload/checksum differs legitimately after dedup
        # and accepted checksum annotation. It is diagnostic, not future state:
        # identity/order, protocol buffers, quality, levels and dedup are retained.
        states = tuple(
            (
                str(stream),
                self.modes[stream],
                replace(
                    loads(reducer.checkpoint().reducer_state, ReducerState),
                    last_event=None,
                ),
            )
            for stream, reducer in sorted(self.reducers.items())
        )
        return sha256(dumps((states, tuple(self.dedup)))).hexdigest()

src/workstation/quality.py.source:
"""Quality is evidence, not transport activity. All consumers share these gates."""

from dataclasses import dataclass, field
from decimal import Decimal
from typing import TYPE_CHECKING, Literal

from .precision import choice, decimal, nonnegative_int, text

if TYPE_CHECKING:
    from .book import Book
    from .instruments import Instrument

SourceMode = Literal["ws_delta", "ws_snapshot", "rest_snapshot", "replay", "demo"]
SOURCE_MODES = ("ws_delta", "ws_snapshot", "rest_snapshot", "replay", "demo")
LIFECYCLES = (
    "starting",
    "waiting_snapshot",
    "synchronizing",
    "live",
    "degraded",
    "stale",
    "resynchronizing",
    "disconnected",
    "unsupported",
    "blocked",
)


@dataclass(frozen=True)
class ClockReading:
    clock_id: str
    mono_ns: int
    wall_ns: int | None = None

    def __post_init__(self):
        text(self.clock_id)
        nonnegative_int(self.mono_ns)
        if self.wall_ns is not None:
            nonnegative_int(self.wall_ns)


@dataclass(frozen=True)
class Coverage:
    subscribed_depth: int | None = None
    retained_bid_levels: int = 0
    retained_ask_levels: int = 0
    worst_bid: Decimal | None = None
    worst_ask: Decimal | None = None
    full_depth: bool = False
    source_aggregation: tuple[tuple[str, str], ...] = ()
    expected_cadence_ns: int | None = None

    def __post_init__(self):
        for retained_levels in (self.retained_bid_levels, self.retained_ask_levels):
            nonnegative_int(retained_levels)
        for coverage_bound in (self.subscribed_depth, self.expected_cadence_ns):
            if coverage_bound is not None and nonnegative_int(coverage_bound) == 0:
                raise ValueError("coverage bound must be positive")
        for name in ("worst_bid", "worst_ask"):
            worst_price = getattr(self, name)
            if worst_price is not None:
                object.__setattr__(self, name, decimal(worst_price, positive=True))
        if type(self.full_depth) is not bool:
            raise ValueError("full_depth must be boolean")
        object.__setattr__(
            self,
            "source_aggregation",
            tuple(tuple(pair) for pair in self.source_aggregation),
        )
        for pair in self.source_aggregation:
            if len(pair) != 2:
                raise ValueError("invalid source aggregation")
            for aggregation_text in pair:
                text(aggregation_text)


@dataclass(frozen=True)
class Capabilities:
    snapshot: bool = True
    deltas: bool = False
    trades: bool = False
    sequence_scope: str | None = None
    checksum_scope: str | None = None
    exact_event_flow: bool = False
    reference_prices: frozenset[str] = frozenset()
    asset_context: frozenset[str] = frozenset()

    def __post_init__(self):
        for value in (self.snapshot, self.deltas, self.trades, self.exact_event_flow):
            if type(value) is not bool:
                raise ValueError("capability must be boolean")
        object.__setattr__(self, "reference_prices", frozenset(self.reference_prices))
        object.__setattr__(self, "asset_context", frozenset(self.asset_context))
        if self.exact_event_flow and not self.deltas:
            raise ValueError("exact event flow requires deltas")


@dataclass(frozen=True)
class Quality:
    lifecycle: str = "waiting_snapshot"
    integrity: str = "unknown"
    transport_alive: bool = False
    source_mode: SourceMode = "ws_snapshot"
    recorded_source_mode: SourceMode | None = None
    last_transport_mono_ns: int | None = None
    last_book_observation_mono_ns: int | None = None
    last_book_change_mono_ns: int | None = None
    last_healthy_observation_mono_ns: int | None = None
    clock_id: str = "unset"
    coverage: Coverage = field(default_factory=Coverage)
    capabilities: Capabilities = field(default_factory=Capabilities)
    continuous_since_ordinal: int | None = None
    reason_codes: tuple[str, ...] = ()
    capture_complete: bool = True

    def __post_init__(self):
        choice(self.lifecycle, LIFECYCLES, "lifecycle")
        choice(self.integrity, ("unknown", "valid", "invalid"), "integrity")
        choice(self.source_mode, SOURCE_MODES, "source mode")
        if self.recorded_source_mode is not None:
            choice(self.recorded_source_mode, SOURCE_MODES, "recorded source mode")
        text(self.clock_id)
        for value in (
            self.last_transport_mono_ns,
            self.last_book_observation_mono_ns,
            self.last_book_change_mono_ns,
            self.last_healthy_observation_mono_ns,
            self.continuous_since_ordinal,
        ):
            if value is not None:
                nonnegative_int(value)
        if not isinstance(self.coverage, Coverage) or not isinstance(
            self.capabilities, Capabilities
        ):
            raise ValueError("invalid quality evidence")
        if (
            type(self.transport_alive) is not bool
            or type(self.capture_complete) is not bool
        ):
            raise ValueError("quality flags must be boolean")
        object.__setattr__(self, "reason_codes", tuple(self.reason_codes))
        for reason in self.reason_codes:
            text(reason)


@dataclass(frozen=True)
class EligibilityPolicy:
    max_age_ns: int = 5_000_000_000
    max_asof_skew_ns: int = 1_000_000_000
    allow_snapshot_quotes: bool = True
    require_execution_access: bool = False
    required_capabilities: frozenset[str] = frozenset()
    version: str = "eligibility-v1"

    def __post_init__(self):
        nonnegative_int(self.max_age_ns)
        nonnegative_int(self.max_asof_skew_ns)
        text(self.version)
        object.__setattr__(
            self, "required_capabilities", frozenset(self.required_capabilities)
        )
        if not self.required_capabilities <= {
            "snapshot",
            "deltas",
            "trades",
            "exact_event_flow",
            "sequence",
            "checksum",
        }:
            raise ValueError("unknown required capability")


@dataclass(frozen=True)
class Eligibility:
    eligible: bool
    reasons: tuple[str, ...]
    evaluated_at_mono_ns: int
    policy_version: str

    def __post_init__(self):
        nonnegative_int(self.evaluated_at_mono_ns)
        text(self.policy_version)
        object.__setattr__(self, "reasons", tuple(self.reasons))
        if type(self.eligible) is not bool or self.eligible != (not self.reasons):
            raise ValueError("eligibility and reasons disagree")


def evaluate(
    book: "Book",
    instrument: "Instrument",
    purpose: str,
    now: ClockReading,
    policy: EligibilityPolicy = EligibilityPolicy(),
) -> Eligibility:
    choice(
        purpose,
        ("display", "comparison", "depth_walk", "event_ofi", "alert", "paper_fill"),
        "purpose",
    )
    reasons: list[str] = []
    quality = book.quality
    if (book.instrument_id, book.metadata_version) != (
        instrument.instrument_id,
        instrument.metadata_version,
    ):
        reasons.append("instrument_mismatch")
    if instrument.status != "active":
        reasons.append("instrument_" + instrument.status)
    readable_observation = (
        quality.integrity == "valid"
        and quality.last_book_observation_mono_ns is not None
        and quality.last_healthy_observation_mono_ns is not None
    )
    if instrument.data_access in ("blocked", "unsupported") or (
        instrument.data_access == "unknown" and not readable_observation
    ):
        reasons.append("data_access_" + instrument.data_access)
    if policy.require_execution_access and instrument.execution_access != "available":
        reasons.append("execution_access_" + instrument.execution_access)
    if quality.integrity != "valid":
        reasons.append("integrity_" + quality.integrity)
    if quality.lifecycle not in ("live", "degraded"):
        reasons.append("lifecycle_" + quality.lifecycle)
    if quality.lifecycle == "degraded" and quality.source_mode != "rest_snapshot":
        reasons.append("degraded")
    if not quality.transport_alive:
        reasons.append("transport_dead")
    if quality.clock_id != now.clock_id or book.asof.clock_id != now.clock_id:
        reasons.append("clock_mismatch")
    else:
        observed = quality.last_healthy_observation_mono_ns
        if observed is None:
            reasons.append("no_healthy_observation")
        elif observed > now.mono_ns or book.asof.receive_mono_ns > now.mono_ns:
            reasons.append("clock_regression")
        elif now.mono_ns - observed > policy.max_age_ns:
            reasons.append("stale")
    mode = quality.recorded_source_mode or quality.source_mode
    if not policy.allow_snapshot_quotes and mode in ("ws_snapshot", "rest_snapshot"):
        reasons.append("snapshot_quotes_disabled")
    if not book.bids or not book.asks:
        reasons.append("empty_side")
    elif book.bids[0].price >= book.asks[0].price:
        reasons.append("crossed_or_locked")
    required = policy.required_capabilities | (
        {"exact_event_flow"} if purpose == "event_ofi" else set()
    )
    for capability in sorted(required):
        supported = (
            getattr(quality.capabilities, capability + "_scope", None)
            if capability in ("sequence", "checksum")
            else getattr(quality.capabilities, capability)
        )
        if not supported:
            reasons.append("missing_" + capability)
    if purpose == "event_ofi" and (
        quality.continuous_since_ordinal is None
        or mode in ("rest_snapshot", "ws_snapshot")
    ):
        reasons.append("no_event_continuity")
    return Eligibility(
        not reasons, tuple(dict.fromkeys(reasons)), now.mono_ns, policy.version
    )


@dataclass(frozen=True)
class CohortEligibility:
    eligible: bool
    reasons: tuple[str, ...]
    members: tuple[tuple[str, Eligibility], ...]

    def __post_init__(self):
        object.__setattr__(self, "reasons", tuple(self.reasons))
        object.__setattr__(
            self, "members", tuple(tuple(member) for member in self.members)
        )
        if self.eligible != (
            not self.reasons and all(item.eligible for _, item in self.members)
        ):
            raise ValueError("inconsistent cohort eligibility")


def evaluate_cohort(
    books: tuple["Book", ...],
    instruments: tuple["Instrument", ...],
    now: ClockReading,
    policy: EligibilityPolicy = EligibilityPolicy(),
) -> CohortEligibility:
    """Exact native-quote cohorts only. Conversion is a separate explicit cost-engine operation."""
    if len(books) != len(instruments):
        raise ValueError("one metadata record is required per book")
    members = tuple(
        (book.instrument_id, evaluate(book, instrument, "comparison", now, policy))
        for book, instrument in zip(books, instruments, strict=True)
    )
    reasons = []
    if not books:
        reasons.append("empty_cohort")
    identities = {
        (
            item.base.asset_id,
            item.quote.asset_id,
            item.market_type,
            item.settlement.asset_id if item.settlement else None,
            item.expiry_wall_ns,
            item.quantity_unit,
            item.contract_multiplier,
            item.contract_value_currency,
            item.inverse,
        )
        for item in instruments
    }
    if len(identities) > 1:
        reasons.append("incompatible_instruments")
    if len({book.instrument_id for book in books}) != len(books):
        reasons.append("duplicate_instrument")
    if books and len({book.asof.clock_id for book in books} | {now.clock_id}) != 1:
        reasons.append("clock_mismatch")
    elif (
        books
        and max(book.asof.receive_mono_ns for book in books)
        - min(book.asof.receive_mono_ns for book in books)
        > policy.max_asof_skew_ns
    ):
        reasons.append("asof_skew")
    return CohortEligibility(
        not reasons and all(item.eligible for _, item in members),
        tuple(reasons),
        members,
    )


@dataclass(frozen=True)
class TradeEvidence:
    """Independent public trade-channel evidence; never a fabricated book."""

    instrument_id: str
    metadata_version: str
    stream_id: str
    clock_id: str
    connection_epoch: int
    established_mono_ns: int | None = None
    last_validated_mono_ns: int | None = None
    healthy: bool = False
    reason_codes: tuple[str, ...] = ()
    continuity_scope: str = "validated_public_channel_not_matching_engine"

    def __post_init__(self):
        for value in (
            self.instrument_id,
            self.metadata_version,
            self.stream_id,
            self.clock_id,
            self.continuity_scope,
        ):
            text(value)
        nonnegative_int(self.connection_epoch)
        for clock_ns in (self.established_mono_ns, self.last_validated_mono_ns):
            if clock_ns is not None:
                nonnegative_int(clock_ns)
        if type(self.healthy) is not bool:
            raise ValueError("invalid trade evidence health")
        if self.healthy and (
            self.established_mono_ns is None or self.last_validated_mono_ns is None
        ):
            raise ValueError("healthy trade evidence requires establishment")
        object.__setattr__(self, "reason_codes", tuple(self.reason_codes))
        for reason in self.reason_codes:
            text(reason)


def evaluate_trades(
    evidence: TradeEvidence | None,
    instrument: "Instrument",
    now: ClockReading,
    policy: EligibilityPolicy = EligibilityPolicy(),
) -> Eligibility:
    """Gate actual validated trades, independently of book availability."""
    reasons: list[str] = []
    if instrument.status != "active":
        reasons.append("instrument_" + instrument.status)
    established = evidence is not None and evidence.established_mono_ns is not None
    if instrument.data_access in ("blocked", "unsupported") or (
        instrument.data_access == "unknown" and not established
    ):
        reasons.append("data_access_" + instrument.data_access)
    if evidence is None:
        reasons.append("no_trade_evidence")
    else:
        if (evidence.instrument_id, evidence.metadata_version) != (
            instrument.instrument_id,
            instrument.metadata_version,
        ):
            reasons.append("instrument_mismatch")
        if not established:
            reasons.append("trade_history_unanchored")
        if not evidence.healthy:
            reasons.append("trade_channel_unhealthy")
        reasons.extend(evidence.reason_codes)
        if evidence.clock_id != now.clock_id:
            reasons.append("clock_mismatch")
        elif evidence.last_validated_mono_ns is None:
            reasons.append("no_validated_trade_observation")
        elif evidence.last_validated_mono_ns > now.mono_ns:
            reasons.append("clock_regression")
        elif now.mono_ns - evidence.last_validated_mono_ns > policy.max_age_ns:
            reasons.append("stale_trade_channel")
    return Eligibility(
        not reasons, tuple(dict.fromkeys(reasons)), now.mono_ns, policy.version
    )


@dataclass(frozen=True)
class ContextEvidence:
    """Independent validated reference/context evidence, never book health."""

    instrument_id: str
    metadata_version: str
    stream_id: str
    channel: str
    clock_id: str
    last_validated_mono_ns: int | None = None
    reason_codes: tuple[str, ...] = ()

    def __post_init__(self):
        for value in (
            self.instrument_id,
            self.metadata_version,
            self.stream_id,
            self.clock_id,
        ):
            text(value)
        choice(self.channel, ("reference", "context"), "context channel")
        if self.last_validated_mono_ns is not None:
            nonnegative_int(self.last_validated_mono_ns)
        object.__setattr__(self, "reason_codes", tuple(self.reason_codes))
        for reason in self.reason_codes:
            text(reason)


def evaluate_context(
    evidence: ContextEvidence | None,
    instrument: "Instrument",
    now: ClockReading | None,
    policy: EligibilityPolicy = EligibilityPolicy(),
) -> Eligibility:
    """Reference freshness does not imply executable depth or trade continuity."""
    reasons: list[str] = []
    if instrument.status != "active":
        reasons.append("instrument_" + instrument.status)
    established = evidence is not None and evidence.last_validated_mono_ns is not None
    if instrument.data_access in ("blocked", "unsupported") or (
        instrument.data_access == "unknown" and not established
    ):
        reasons.append("data_access_" + instrument.data_access)
    if now is None:
        reasons.append("clock_unavailable")
    if evidence is None:
        reasons.append("no_context_evidence")
    else:
        if (evidence.instrument_id, evidence.metadata_version) != (
            instrument.instrument_id,
            instrument.metadata_version,
        ):
            reasons.append("instrument_mismatch")
        reasons.extend(evidence.reason_codes)
        if evidence.last_validated_mono_ns is None:
            reasons.append("no_validated_context_observation")
        if now is not None:
            if evidence.clock_id != now.clock_id:
                reasons.append("clock_mismatch")
            elif evidence.last_validated_mono_ns is not None:
                if evidence.last_validated_mono_ns > now.mono_ns:
                    reasons.append("clock_regression")
                elif now.mono_ns - evidence.last_validated_mono_ns > policy.max_age_ns:
                    reasons.append("stale_context_channel")
    return Eligibility(
        not reasons,
        tuple(dict.fromkeys(reasons)),
        now.mono_ns if now is not None else 0,
        policy.version,
    )

